{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Bumetanide, the closest structural analogue sharing the sulfamoylbenzoic acid and phenoxy scaffold, has an absolute oral bioavailability of 90% in healthy subjects, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "In 12 normal adult volunteers, bumetanide oral solution absolute bioavailability was 0.69, still well above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Bumetanide oral tablet absolute bioavailability was 0.86 ± 0.13 in normal subjects, providing additional consistent evidence for high oral bioavailability in this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close analogue of bumetanide, differing mainly by a pyrrolidine substituent instead of a butylamino group. Bumetanide consistently shows high absolute oral bioavailability in humans (roughly 69-95%), far above the 20% threshold. The shared sulfamoylbenzoic acid/phenoxy scaffold and similar aniline-type amine support transfer of high F to the query.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule; prediction relies on the close analogue bumetanide.",
    "The effect of replacing the n-butylamino group with pyrrolidine on first-pass metabolism and solubility is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

